css:
.recipe-container {
  font-family: "Inter", sans-serif;
  padding: 25px;
  background: linear-gradient(120deg, #f9fefc, #e6f7f5); /* very light gradient */
  border-radius: 16px;
  color: #333;
}

.recipe-header {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-bottom: 30px;
  background: linear-gradient(90deg, #dffaf6, #c8f1eb); /* light pastel header */
  padding: 15px 20px;
  border-radius: 16px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.05);
}

.recipe-header img {
  width: 120px;
  height: 120px;
  object-fit: cover;
  border-radius: 16px;
  border: 2px solid #fff;
  box-shadow: 0 2px 8px rgba(0,0,0,0.08);
}

.recipe-title {
  flex: 1;
}

.recipe-title h2 {
  font-size: 1.5rem;
  margin: 0;
  color: #2e7d7f; 
}

.recipe-title p {
  margin: 6px 0 0;
  color: #555;
  font-weight: 500;
}

.ingredients {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 20px;
  margin-top: 20px;
}

.ingredient-card {
  border-radius: 16px;
  padding: 12px;
  text-align: center;
  background: linear-gradient(145deg, #f0fefa, #dffaf6); /* soft pastel card */
  box-shadow: 0 4px 15px rgba(0,0,0,0.05);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.ingredient-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 20px rgba(0,0,0,0.1);
}

.ingredient-card img {
  width: 90px;
  height: 90px;
  object-fit: cover;
  border-radius: 12px;
  margin-bottom: 10px;
  border: 1px solid #b2f0ea; /* soft pastel border */
}

.ingredient-name {
  font-weight: 700;
  color: #2e7d7f;
  margin-bottom: 4px;
}

.ingredient-qty {
  font-size: 0.95rem;
  color: #555;
  font-weight: 500;
}

.section-title {
  font-size: 1.3rem;
  color: #2e7d7f;
  margin-bottom: 10px;
  border-bottom: 2px solid #b2f0ea;
  padding-bottom: 5px;
}
